sealed class TalkException: kotlin.Exception() {
    
    /**
     * Bad input from the host (a rate Opus cannot code, a frame size).
     */
    class Invalid(
        
        val `reason`: kotlin.String
        ) : TalkException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The codec failed on this frame or packet; the coder stays usable.
     */
    class Codec(
        
        val `reason`: kotlin.String
        ) : TalkException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<TalkException> {
        override fun lift(error_buf: RustBuffer.ByValue): TalkException = FfiConverterTypeTalkError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeTalkError : FfiConverterRustBuffer<TalkException> {
    override fun read(buf: ByteBuffer): TalkException {
        

        return when(buf.getInt()) {
            1 -> TalkException.Invalid(
                FfiConverterString.read(buf),
                )
            2 -> TalkException.Codec(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: TalkException): ULong {
        return when(value) {
            is TalkException.Invalid -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is TalkException.Codec -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: TalkException, buf: ByteBuffer) {
        when(value) {
            is TalkException.Invalid -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is TalkException.Codec -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
